import Fastify from 'fastify'
import type { LocationConfig } from './config.ts'
import { RequestError, readMarkdownFile, writeMarkdownFile, type ReadFile } from './files.ts'
import { parseMutationBody, performMutation } from './mutations.ts'
import { LocationRegistry } from './registry.ts'

export type { Source } from './config.ts'
export type { Entry, EntryKind, Listing, LocationStatus } from './registry.ts'

export type AppOptions = {
  /** Injectable for tests that simulate a filesystem read failure deterministically. */
  readFile?: ReadFile
}

function singleString(value: unknown): string | null {
  return typeof value === 'string' ? value : null
}

/** Request bodies above this size are rejected with 413 before any file is touched. */
export const REQUEST_BODY_LIMIT = 8 * 1024 * 1024

const HASH_PATTERN = /^[0-9a-f]{64}$/

type WriteBody = { source: string; locationId: string; path: string; content: string; expectedHash: string }

function parseWriteBody(body: unknown): WriteBody {
  if (!body || typeof body !== 'object' || Array.isArray(body)) {
    throw new RequestError(400, 'INVALID_BODY', 'The request body must be a JSON object with source, locationId, path, content and expectedHash.')
  }
  const { source, locationId, path, content, expectedHash } = body as Record<string, unknown>
  if (typeof source !== 'string') throw new RequestError(400, 'INVALID_SOURCE', 'The source must be Pi or Claude.')
  if (typeof locationId !== 'string' || locationId.length === 0) throw new RequestError(400, 'INVALID_LOCATION', 'The locationId must name a configured location.')
  if (typeof path !== 'string') throw new RequestError(400, 'INVALID_PATH', 'The file path is invalid.')
  if (typeof content !== 'string') throw new RequestError(400, 'INVALID_CONTENT', 'The content must be a string.')
  if (typeof expectedHash !== 'string' || !HASH_PATTERN.test(expectedHash)) {
    throw new RequestError(400, 'INVALID_HASH', 'The expected hash must be the 64-character lowercase SHA-256 from the last read or save.')
  }
  return { source, locationId, path, content, expectedHash }
}

/**
 * The HTTP API over a fixed set of configured locations. Locations are startup configuration: no request can
 * add, change or select a root, and responses never carry absolute paths, file content of other files or
 * stack traces.
 */
export function createApp(locations: readonly LocationConfig[], options: AppOptions = {}) {
  const app = Fastify({ logger: true, bodyLimit: REQUEST_BODY_LIMIT })
  const registry = new LocationRegistry(locations, {
    // Log only the error code and location id: messages can carry absolute paths.
    warn: (error, location) => app.log.error({ id: location.id, code: (error as NodeJS.ErrnoException)?.code }, 'Location listing failed'),
  })
  // Body parsing failures (too large, malformed or non-JSON) must be safe JSON with a stable code.
  app.setErrorHandler((error: { statusCode?: number; code?: string }, _request, reply) => {
    const status = typeof error.statusCode === 'number' ? error.statusCode : 500
    if (status === 413) return reply.code(413).send({ code: 'REQUEST_TOO_LARGE', error: `The request is larger than the ${REQUEST_BODY_LIMIT / (1024 * 1024)} MiB limit. Shorten the document or copy your draft elsewhere.` })
    if (status === 415) return reply.code(415).send({ code: 'UNSUPPORTED_MEDIA_TYPE', error: 'The request body must be JSON.' })
    if (status >= 400 && status < 500) return reply.code(status).send({ code: 'INVALID_BODY', error: 'The request body could not be read as JSON.' })
    app.log.error({ code: error.code }, 'Unhandled request failure')
    return reply.code(500).send({ code: 'INTERNAL', error: 'The request failed unexpectedly.' })
  })
  app.addHook('onReady', async () => { await registry.open() })
  app.addHook('onClose', async () => { await registry.close() })
  app.get('/api/entries', async (_request, reply) => {
    try {
      return await registry.list()
    } catch (error) {
      app.log.error({ code: (error as NodeJS.ErrnoException)?.code }, 'Listing failed')
      return reply.code(500).send({ code: 'LISTING_FAILED', error: 'Unable to list the configured locations. Refresh to retry.' })
    }
  })
  app.get('/api/file', async (request, reply) => {
    const query = request.query as Record<string, unknown>
    const source = singleString(query.source)
    const locationId = singleString(query.locationId)
    const path = singleString(query.path)
    if (source === null || path === null) {
      return reply.code(400).send({ code: 'INVALID_QUERY', error: 'The source, locationId and path query parameters are each required exactly once.' })
    }
    if (locationId === null) {
      return reply.code(400).send({ code: 'INVALID_LOCATION', error: 'The locationId query parameter is required exactly once.' })
    }
    try {
      const document = await readMarkdownFile(registry, source, locationId, path, options.readFile)
      return reply.header('Cache-Control', 'no-store').send(document)
    } catch (error) {
      if (error instanceof RequestError) return reply.code(error.status).send({ code: error.code, error: error.message })
      app.log.error({ code: (error as NodeJS.ErrnoException)?.code }, 'File read failed')
      return reply.code(500).send({ code: 'READ_FAILED', error: 'The file could not be read. Check that it is readable, then retry.' })
    }
  })
  app.put('/api/file', async (request, reply) => {
    try {
      const body = parseWriteBody(request.body)
      const result = await writeMarkdownFile(registry, body.source, body.locationId, body.path, body.content, body.expectedHash)
      return reply.header('Cache-Control', 'no-store').send(result)
    } catch (error) {
      if (error instanceof RequestError) return reply.code(error.status).send({ code: error.code, error: error.message })
      app.log.error({ code: (error as NodeJS.ErrnoException)?.code }, 'File write failed')
      return reply.code(500).send({ code: 'WRITE_FAILED', error: 'The file could not be written. Your draft is unchanged; retry or copy it.' })
    }
  })
  app.post('/api/mutate', async (request, reply) => {
    try {
      const mutation = parseMutationBody(request.body)
      const result = await performMutation(registry, mutation)
      return reply.code(result.status).header('Cache-Control', 'no-store').send(result.body)
    } catch (error) {
      if (error instanceof RequestError) return reply.code(error.status).send({ code: error.code, error: error.message })
      const code = (error as NodeJS.ErrnoException)?.code
      if (code === 'ENOENT' || code === 'ENOTDIR' || code === 'ELOOP') {
        return reply.code(404).send({ code: 'NOT_FOUND', error: 'The target or its folder was not found.' })
      }
      app.log.error({ code }, 'Mutation failed')
      return reply.code(500).send({ code: 'MUTATION_FAILED', error: 'The operation failed unexpectedly. Refresh the listing to see the current state.' })
    }
  })
  return app
}
import { readFile, realpath } from 'node:fs/promises'
import { homedir } from 'node:os'
import { isAbsolute, join, resolve, sep } from 'node:path'
import { fileURLToPath } from 'node:url'

/**
 * Startup configuration: which filesystem locations the app manages, grouped under the two agents.
 * Everything here is trusted administrator input read once at startup; requests can never add,
 * change or select a root. Automated tests pass explicit environments so a live config in HOME is
 * never discovered by accident.
 */
export type Source = 'Pi' | 'Claude'
export const SOURCES: readonly Source[] = ['Pi', 'Claude']
export type Category = 'personal' | 'package' | 'plugin' | 'project'
export const CATEGORIES: readonly Category[] = ['personal', 'package', 'plugin', 'project']

export type LocationConfig = {
  /** Stable, URL-safe identity; labels may change, ids must not. */
  id: string
  source: Source
  label: string
  /** Absolute directory, normalized (no trailing separator). */
  path: string
  category: Category
}

export type AppConfig = { mode: 'live' | 'fixture'; locations: LocationConfig[]; configPath?: string }

/** A configuration problem: the message is a local startup diagnostic and may name configured paths. */
export class ConfigError extends Error {}

export const CONFIG_ENV = 'MD_MANAGER_CONFIG'
export const FIXTURE_ENV = 'MD_MANAGER_FIXTURE_ROOT'
const ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/
const SUPPORTED_VERSION = 1

export function defaultConfigPath(env: NodeJS.ProcessEnv): string {
  const home = env.HOME?.trim() || homedir()
  return join(home, '.config', 'md-manager', 'sources.json')
}

/** The repository's fixtures/ folder, resolved from this module rather than the shell's working directory. */
export const defaultFixtureRoot = fileURLToPath(new URL('../fixtures/', import.meta.url))

/** Explicit fixture/demo mode: `<root>/pi` and `<root>/claude` become one location per source. */
export function fixtureLocations(root: string): LocationConfig[] {
  const base = resolve(root)
  return [
    { id: 'pi-fixtures', source: 'Pi', label: 'Fixtures', path: join(base, 'pi'), category: 'personal' },
    { id: 'claude-fixtures', source: 'Claude', label: 'Fixtures', path: join(base, 'claude'), category: 'personal' },
  ]
}

function isSource(value: unknown): value is Source {
  return value === 'Pi' || value === 'Claude'
}

function isCategory(value: unknown): value is Category {
  return typeof value === 'string' && (CATEGORIES as readonly string[]).includes(value)
}

/** Lexical validation of every location; nothing on disk is consulted. */
export function validateLocations(locations: unknown): LocationConfig[] {
  if (!Array.isArray(locations)) throw new ConfigError('"locations" must be an array of location objects.')
  if (locations.length === 0) throw new ConfigError('"locations" must contain at least one location.')
  const validated: LocationConfig[] = []
  const ids = new Map<string, number>()
  locations.forEach((entry, index) => {
    const where = `locations[${index}]`
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) throw new ConfigError(`${where} must be an object with id, source, label, path and category.`)
    const record = entry as Record<string, unknown>
    const { id, source, label, path, category } = record
    if (typeof id !== 'string' || !ID_PATTERN.test(id)) {
      throw new ConfigError(`${where}: "id" must be 1-64 characters of letters, digits, ".", "_" or "-", starting with a letter or digit (got ${JSON.stringify(id)}).`)
    }
    if (!isSource(source)) throw new ConfigError(`${where} (id "${id}"): "source" must be "Pi" or "Claude" (got ${JSON.stringify(source)}).`)
    if (typeof label !== 'string' || label.trim().length === 0) throw new ConfigError(`${where} (id "${id}"): "label" must be a non-empty string.`)
    if (typeof path !== 'string' || path.length === 0 || path.includes('\0')) throw new ConfigError(`${where} (id "${id}"): "path" must be a non-empty string without NUL characters.`)
    if (!isAbsolute(path) || path.startsWith('~')) throw new ConfigError(`${where} (id "${id}"): "path" must be absolute; "~", environment variables and relative paths are not expanded (got ${JSON.stringify(path)}).`)
    const normalized = resolve(path)
    if (normalized === sep) throw new ConfigError(`${where} (id "${id}"): "path" must not be the filesystem root.`)
    if (!isCategory(category)) throw new ConfigError(`${where} (id "${id}"): "category" must be one of ${CATEGORIES.join(', ')} (got ${JSON.stringify(category)}).`)
    const previous = ids.get(id)
    if (previous !== undefined) throw new ConfigError(`Duplicate location id "${id}" at locations[${previous}] and ${where}. Ids must be unique and stable.`)
    ids.set(id, index)
    validated.push({ id, source, label: label.trim(), path: normalized, category })
  })
  return validated
}

/** Resolves aliases where the path exists so two spellings of one directory are caught. */
async function canonical(path: string): Promise<string> {
  try {
    return await realpath(path)
  } catch {
    return path
  }
}

function contains(parent: string, child: string): boolean {
  return child === parent || child.startsWith(parent.endsWith(sep) ? parent : `${parent}${sep}`)
}

/** Rejects identical, nested or aliased roots: every file must belong to exactly one location. */
export async function assertDisjointRoots(locations: readonly LocationConfig[]): Promise<void> {
  const canonicals = await Promise.all(locations.map(location => canonical(location.path)))
  for (let i = 0; i < locations.length; i += 1) {
    for (let j = i + 1; j < locations.length; j += 1) {
      const a = { ...locations[i], canonical: canonicals[i] }
      const b = { ...locations[j], canonical: canonicals[j] }
      if (contains(a.canonical, b.canonical) || contains(b.canonical, a.canonical)) {
        throw new ConfigError(`Locations "${a.id}" (${a.path}) and "${b.id}" (${b.path}) overlap: roots must be distinct directories, not the same directory, aliases of each other or nested.`)
      }
    }
  }
}

/** Pi first, then Claude; configured order is preserved within each source. */
export function orderLocations(locations: readonly LocationConfig[]): LocationConfig[] {
  return SOURCES.flatMap(source => locations.filter(location => location.source === source))
}

/** Parses and fully validates configuration text. `describe` names the file for diagnostics. */
export async function parseConfig(text: string, describe: string): Promise<LocationConfig[]> {
  let parsed: unknown
  try {
    parsed = JSON.parse(text)
  } catch (error) {
    throw new ConfigError(`${describe} is not valid JSON: ${(error as Error).message}`)
  }
  try {
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new ConfigError('the top level must be an object with "version" and "locations".')
    const record = parsed as Record<string, unknown>
    if (record.version !== SUPPORTED_VERSION) throw new ConfigError(`"version" must be the number ${SUPPORTED_VERSION} (got ${JSON.stringify(record.version)}).`)
    const locations = orderLocations(validateLocations(record.locations))
    await assertDisjointRoots(locations)
    return locations
  } catch (error) {
    if (error instanceof ConfigError) throw new ConfigError(`${describe}: ${error.message}`)
    throw error
  }
}

function setting(env: NodeJS.ProcessEnv, name: string): string | null {
  const value = env[name]?.trim()
  return value ? value : null
}

/**
 * Resolves the startup mode from an explicit environment object. Live mode reads MD_MANAGER_CONFIG or the
 * default file; fixture mode is only ever selected explicitly. Missing or invalid configuration fails
 * startup: there is no silent fallback to the repository fixtures.
 */
export async function loadConfig(env: NodeJS.ProcessEnv): Promise<AppConfig> {
  const configSetting = setting(env, CONFIG_ENV)
  const fixtureSetting = setting(env, FIXTURE_ENV)
  if (configSetting && fixtureSetting) {
    throw new ConfigError(`Set only one of ${CONFIG_ENV} (live locations) and ${FIXTURE_ENV} (fixture demo mode); both are set.`)
  }
  if (fixtureSetting) return { mode: 'fixture', locations: fixtureLocations(fixtureSetting) }
  const configPath = configSetting ? resolve(configSetting) : defaultConfigPath(env)
  let text: string
  try {
    text = await readFile(configPath, 'utf8')
  } catch (error) {
    const code = (error as NodeJS.ErrnoException).code
    const reason = code === 'ENOENT' ? 'does not exist' : `could not be read (${code ?? 'unknown error'})`
    throw new ConfigError(
      `Configuration file ${configPath} ${reason}. Create it from config/sources.example.json (see README "Live skills"), `
      + `point ${CONFIG_ENV} at another file, or set ${FIXTURE_ENV} for the fixture demo. The app never falls back to fixtures on its own.`,
    )
  }
  return { mode: 'live', configPath, locations: await parseConfig(text, configPath) }
}
import { createApp, type LocationStatus } from './app.ts'
import { ConfigError, loadConfig, type AppConfig } from './config.ts'

// Configuration is read once, before anything listens. A missing or invalid config is a startup failure
// with a local diagnostic (which may name configured paths); there is no fallback to the fixtures.
let config: AppConfig
try {
  config = await loadConfig(process.env)
} catch (error) {
  if (error instanceof ConfigError) {
    console.error(`md-manager: ${error.message}`)
    process.exit(1)
  }
  throw error
}

const app = createApp(config.locations)
try {
  await app.listen({ port: Number(process.env.MD_MANAGER_API_PORT ?? 3001), host: '127.0.0.1' })
  app.log.info({ mode: config.mode, configPath: config.configPath ?? null, locations: config.locations.length }, 'Configuration loaded')
  // Per-location startup status: unavailable locations are a warning, never a startup failure.
  const { locations } = (await app.inject('/api/entries')).json() as { locations: LocationStatus[] }
  for (const status of locations) {
    const configured = config.locations.find(location => location.id === status.id)
    const details = { id: status.id, source: status.source, category: status.category, path: configured?.path }
    if (status.status === 'available') app.log.info(details, 'Location available')
    else app.log.warn({ ...details, error: status.error }, 'Location unavailable')
  }
} catch (error) {
  app.log.error(error)
  process.exitCode = 1
}
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.once(signal, () => { void app.close() })
}
import fs, { type FileHandle } from 'node:fs/promises'
import { constants } from 'node:fs'
import { orderLocations, type Category, type LocationConfig, type Source } from './config.ts'
import { DIRECTORY_FLAGS, EXCLUDED_DIRECTORY, MutationQueue, PathError, RequestError, at, isMarkdownName, isSource } from './files.ts'

/**
 * The set of configured filesystem locations and the only way to reach one of their roots.
 *
 * Roots are trusted administrator configuration; requests select a location by id and are validated
 * lexically against the configured source. A root is opened no-follow for the duration of exactly one
 * operation (a listing, a read or a queued mutation), so a root that is deleted, replaced or turned into a
 * symlink afterwards can never redirect that operation: descriptor-relative steps continue on the pinned
 * original, and the next operation re-opens the configured path and reports it unavailable if it no longer
 * is a directory. No handle outlives the operation that opened it, so there is nothing to leak on shutdown.
 */
export const CAPABILITY_ERROR = 'Secure file reads require Linux with mounted procfs at /proc/self/fd.'
const PROC_SUPER_MAGIC = 0x9fa0

export type EntryKind = 'directory' | 'file'
export type Entry = { source: Source; locationId: string; path: string; kind: EntryKind }
export type LocationStatus = {
  id: string
  source: Source
  label: string
  category: Category
  status: 'available' | 'unavailable'
  /** A safe diagnostic without absolute paths, or null when available. */
  error: string | null
}
export type Listing = { locations: LocationStatus[]; entries: Entry[] }

/** The request named no configured location for its source. Nothing on disk was consulted. */
export class LocationError extends RequestError {
  constructor(message: string) { super(400, 'INVALID_LOCATION', message) }
}

/** The location is configured but its root cannot be used right now (missing, replaced by a symlink, unreadable). */
export class LocationUnavailableError extends RequestError {
  constructor(message: string) { super(404, 'LOCATION_UNAVAILABLE', message) }
}

/**
 * Maps a failed no-follow root open to a user-safe reason, or null when the failure is unexpected (reported as
 * 500). Linux reports a symlink opened with O_NOFOLLOW|O_DIRECTORY as ENOTDIR (or ELOOP), so those two are
 * told apart with an lstat of the configured path; the lstat result is only used for the diagnostic.
 */
export async function unavailableReason(path: string, error: unknown): Promise<string | null> {
  switch ((error as NodeJS.ErrnoException)?.code) {
    case 'ENOENT': return 'The configured folder does not exist.'
    case 'ENOTDIR':
    case 'ELOOP': {
      const symlink = await fs.lstat(path).then(stats => stats.isSymbolicLink(), () => false)
      return symlink ? 'The configured folder is a symbolic link; symlinked roots are never followed.' : 'The configured path is not a folder.'
    }
    case 'EACCES':
    case 'EPERM': return 'The configured folder is not readable (permission denied).'
    default: return null
  }
}

/** No pathname fallback: Node lacks openat, so descriptor-relative traversal requires Linux procfs. */
async function probeCapability(): Promise<void> {
  if (process.platform !== 'linux' || !constants.O_NOFOLLOW || !constants.O_DIRECTORY) throw new Error(CAPABILITY_ERROR)
  try {
    const stats = await fs.statfs('/proc/self/fd')
    if (stats.type !== PROC_SUPER_MAGIC) throw new Error('Not procfs')
  } catch (cause) { throw new Error(CAPABILITY_ERROR, { cause }) }
  // Prove that an open descriptor can be re-opened through its magic link before any root is touched.
  const handle = await fs.open('/proc/self/fd', constants.O_RDONLY | constants.O_DIRECTORY)
  try {
    const probe = await fs.open(at(handle), constants.O_RDONLY | constants.O_DIRECTORY)
    await probe.close()
  } catch (cause) {
    throw new Error(CAPABILITY_ERROR, { cause })
  } finally {
    await handle.close()
  }
}

// Byte-wise ordering keeps the listing deterministic regardless of locale.
function byName(a: { name: string }, b: { name: string }) {
  return a.name < b.name ? -1 : a.name > b.name ? 1 : 0
}

/**
 * Lists directories and regular Markdown files below an open directory, descending through no-follow
 * descriptors. Symlinks and `.git` directories are skipped; a directory that vanishes or becomes a symlink
 * between readdir and open is skipped too; an unreadable directory makes the whole location unavailable
 * rather than showing it as empty.
 */
async function walk(directory: FileHandle, location: LocationConfig, prefix: string, entries: Entry[]): Promise<void> {
  const dirents = (await fs.readdir(at(directory), { withFileTypes: true })).sort(byName)
  for (const dirent of dirents) {
    if (dirent.isSymbolicLink()) continue
    const path = prefix ? `${prefix}/${dirent.name}` : dirent.name
    if (dirent.isDirectory()) {
      if (dirent.name === EXCLUDED_DIRECTORY) continue
      let child: FileHandle
      try {
        child = await fs.open(at(directory, dirent.name), DIRECTORY_FLAGS)
      } catch (error) {
        const code = (error as NodeJS.ErrnoException)?.code
        if (code === 'ENOENT' || code === 'ENOTDIR' || code === 'ELOOP') continue
        if (code === 'EACCES' || code === 'EPERM') throw new LocationUnavailableError(`The folder "${path}" is not readable (permission denied).`)
        throw error
      }
      try {
        entries.push({ source: location.source, locationId: location.id, path, kind: 'directory' })
        await walk(child, location, path, entries)
      } finally {
        await child.close()
      }
    } else if (dirent.isFile() && isMarkdownName(dirent.name)) {
      entries.push({ source: location.source, locationId: location.id, path, kind: 'file' })
    }
  }
}

export type RegistryOptions = {
  /** Receives unexpected (non-availability) listing failures for logging; messages may contain paths. */
  warn?: (error: unknown, location: LocationConfig) => void
}

export class LocationRegistry {
  readonly locations: readonly LocationConfig[]
  /** One serial queue for every mutation across all locations: check-then-write steps never interleave. */
  readonly mutations = new MutationQueue()
  private readonly byId = new Map<string, LocationConfig>()
  private readonly warn?: RegistryOptions['warn']
  private state: 'new' | 'open' | 'closed' = 'new'

  /** Pi first, then Claude, configured order within each source; ids must be unique (config.ts enforces both). */
  constructor(locations: readonly LocationConfig[], options: RegistryOptions = {}) {
    this.locations = orderLocations(locations)
    this.warn = options.warn
    for (const location of locations) {
      if (this.byId.has(location.id)) throw new Error(`Duplicate location id "${location.id}"`)
      this.byId.set(location.id, location)
    }
  }

  /** Verifies the platform capability once. Opens no configured root: availability is checked per operation. */
  async open(): Promise<void> {
    if (this.state === 'closed') throw new Error('The location registry is closed.')
    await probeCapability()
    this.state = 'open'
  }

  async close(): Promise<void> {
    this.state = 'closed'
  }

  /** Lexical lookup of a request's location. Unknown ids or a source mismatch are rejected before any disk access. */
  resolve(source: unknown, locationId: unknown): LocationConfig {
    if (!isSource(source)) throw new PathError(400, 'The source must be Pi or Claude.', 'INVALID_SOURCE')
    if (typeof locationId !== 'string' || locationId.length === 0) {
      throw new LocationError('A locationId naming a configured location is required.')
    }
    const location = this.byId.get(locationId)
    if (!location || location.source !== source) {
      throw new LocationError('That location is not configured for this source. Refresh the listing and choose a configured location.')
    }
    return location
  }

  /**
   * Opens the trusted configured root no-follow for one operation and closes it afterwards. The configured
   * path's ancestors are trusted startup configuration; the final component is never followed as a symlink.
   */
  async withRoot<T>(location: LocationConfig, operation: (root: FileHandle) => Promise<T>): Promise<T> {
    if (this.state !== 'open') throw new Error('The location registry is not open.')
    let root: FileHandle
    try {
      root = await fs.open(location.path, DIRECTORY_FLAGS)
    } catch (error) {
      const reason = await unavailableReason(location.path, error)
      if (reason) throw new LocationUnavailableError(`${reason} Refresh the listing to see which locations are available.`)
      throw error
    }
    try {
      return await operation(root)
    } finally {
      await root.close()
    }
  }

  /** Every location with its current availability, plus the entries of the available ones, in configured order. */
  async list(): Promise<Listing> {
    const locations: LocationStatus[] = []
    const entries: Entry[] = []
    for (const location of this.locations) {
      const found: Entry[] = []
      let error: string | null = null
      try {
        await this.withRoot(location, root => walk(root, location, '', found))
      } catch (cause) {
        if (cause instanceof LocationUnavailableError) {
          error = cause.message
        } else {
          error = (await unavailableReason(location.path, cause)) ?? 'The folder could not be listed. Check that it exists and is readable, then refresh.'
          this.warn?.(cause, location)
        }
      }
      locations.push({
        id: location.id, source: location.source, label: location.label, category: location.category,
        status: error === null ? 'available' : 'unavailable', error,
      })
      if (error === null) entries.push(...found)
    }
    return { locations, entries }
  }
}

